args.content:
// Python repr() formatting helpers (str/int/dict/bidict).
// Pure ESM, no dependencies.

// Characters Python str.isprintable() treats as NON-printable:
// general categories Cc, Cf, Cs, Co, Cn, Zl, Zp, Zs (space U+0020 is handled
// separately and kept as-is).
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

function hexEscape(cp) {
  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
  return '\\U' + cp.toString(16).padStart(8, '0');
}

// Python repr() of a str.
export function reprStr(s) {
  // Quote selection: single quotes normally; double quotes if the string
  // contains a single quote but no double quote.
  const hasSingle = s.includes("'");
  const hasDouble = s.includes('"');
  const quote = hasSingle && !hasDouble ? '"' : "'";

  let out = quote;
  for (const ch of s) {
    const cp = ch.codePointAt(0);
    if (ch === '\\') {
      out += '\\\\';
    } else if (ch === quote) {
      out += '\\' + quote;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else if (ch === ' ') {
      out += ' ';
    } else if (NON_PRINTABLE.test(ch)) {
      out += hexEscape(cp);
    } else {
      out += ch;
    }
  }
  out += quote;
  return out;
}

// Python repr()/str() of an int: plain decimal digits, no BigInt "n" suffix.
export function reprInt(b) {
  return b.toString();
}

// repr for a value that is either a Python int (BigInt) or str (string).
export function reprValue(v) {
  return typeof v === 'bigint' ? reprInt(v) : reprStr(v);
}

// Python dict repr from insertion-ordered [key, value] pairs.
export function reprDict(pairs) {
  if (pairs.length === 0) return '{}';
  return '{' + pairs.map(([k, v]) => reprStr(k) + ': ' + reprValue(v)).join(', ') + '}';
}

// bidict repr: bidict({...})
export function reprBidict(pairs) {
  return 'bidict(' + reprDict(pairs) + ')';
}

args.command:
node --input-type=module -e "
import { reprStr, reprInt, reprValue, reprDict, reprBidict } from '/output/lib/pyformat.mjs';
console.log(reprStr('i'));
console.log(reprStr(\"x'y\"));
console.log(reprStr('a\"b'));
console.log(reprStr('both\\'\"'));
console.log(reprStr('back\\\\slash'));
console.log(reprStr('tab\there'));
console.log(reprStr('new\nline'));
console.log(reprStr('café'));
console.log(reprStr('abc d'));
console.log(reprStr(''));
console.log(reprStr(''));
console.log(reprStr('')); 
console.log(reprInt(100000000000000000000n));
console.log(reprInt(-55n));
console.log(reprValue('s'), reprValue(7n));
console.log(reprDict([]));
console.log(reprBidict([['i',55n],['c',95n],['t',92n]]));
"
